// Generated by scripts/embed.mjs from examples/*/smithable*.yml. Do not edit.
export const STARTERS: Record<string, Record<string, string>> = {
  "booking": {"smithable.auth.yml":"# Who signs in, the roles and the default access. Technology-neutral.\nsmithableAuth: 0.1\n\nsignIn:\n  providers: [google, facebook]\n\ndefaultAccess: private             # members only see their own records\n\nroles:\n  admin:\n    description: Studio staff. Manage the schedule, classes and teachers.\n  member:\n    description: A student who books classes.\n\nadmins: [owner@stillwater.ax]\n\n# ⚠ PUBLIC: everything listed here is visible to anyone on the internet, without\n# signing in. Never add models that contain personal or business data.\npublic:\n  pages: [home, sessions]          # the landing page and the schedule\n  read: [ClassType, Instructor, Session]\n","smithable.content.yml":"# What visitors read. Derived from names when not given here.\nsmithableContent: 0.1\n\nmodels:\n  ClassType:\n    fields:\n      level: { values: { allLevels: All levels } }\n\npages:\n  home:\n    hero:\n      title: Find your calm\n      subtitle: Small yoga classes for every level, in the heart of Mariehamn.\n      button: See the schedule\n    classes:\n      title: Our classes\n      text: Something for every level, from first steps to deep stretches.\n    faq:\n      title: Before your first class\n      items:\n        - question: Do I need experience?\n          answer: No. Foundations and all-levels classes are made for beginners.\n        - question: What should I bring?\n          answer: Comfortable clothes and water. Mats are there for you.\n        - question: How do I cancel a booking?\n          answer: Open your booking and cancel it; the spot goes to someone else.\n    callToAction:\n      title: Your first class is waiting\n      button: Book a class\n  sessions:\n    title: Class schedule\n    subtitle: A little time, just for you.\n","smithable.ux.yml":"# How the app looks. Technology-neutral: presets and choices, never CSS.\nsmithableUx: 0.1\n\ntheme:\n  preset: playful\n\npages:\n  sessions:\n    table:\n      columns: [startsAt, classType, instructor, capacity]\n","smithable.yml":"smithable: 0.1\n\napp:\n  name: Stillwater Yoga\n  description: Class schedule and online booking for a small yoga studio.\n  currency: EUR\n  timezone: Europe/Mariehamn\n\nmodels:\n  ClassType:\n    description: A kind of class the studio offers, such as Vinyasa, Yin, Hatha or Foundations.\n    fields:\n      name: string!\n      summary: text\n      level:                            # long form: default is not the first value\n        type: beginner | allLevels | advanced\n        default: allLevels\n      durationMinutes: int! = 60\n    access: { create: [admin] }         # members don't add classes\n\n  Instructor:\n    fields:\n      name: string!\n      bio: text\n    access: { create: [admin] }\n\n  Session:\n    description: One scheduled occurrence of a class.\n    fields:\n      classType: ClassType!\n      instructor: Instructor!\n      startsAt: datetime!\n      capacity: int! = 12\n    access: { create: [admin] }\n    rules:\n      - A session never has more confirmed bookings than its capacity.\n\npages:\n  home:\n    route: /\n    landing:\n      hero: { button: sessions }\n      classes: { records: ClassType }\n      faq:\n      callToAction: { button: sessions }\n  sessions:\n    crud: Session\n  class-types:\n    crud: ClassType\n    access: [admin]\n  instructors:\n    crud: Instructor\n    access: [admin]\n"},
  "crm": {"smithable.auth.yml":"# Who signs in, the roles and the default access. Technology-neutral.\nsmithableAuth: 0.1\n\nsignIn:\n  providers: [google]\n  allowedDomains: [acme.com]       # only Acme's Google Workspace accounts\n\ndefaultAccess: shared              # an internal tool: colleagues see each other's data\n\nroles:\n  admin: { description: Sales management. Full access. }\n  sales: { description: Works with customers and orders. }\n\nadmins: [owner@acme.com]           # become admin when they first sign in\n\n# ⚠ PUBLIC: everything listed here is visible to anyone on the internet, without\n# signing in. Never add models that contain personal or business data.\npublic:\n  pages: []                        # an internal tool: nothing is public\n","smithable.content.yml":"# Visible text. Only what differs from the texts Smithable derives from names.\nsmithableContent: 0.1\n\nmodels:\n  Customer:\n    fields:\n      segment:\n        values: { smb: Small business }\n      creditLimit:\n        help: Orders are held when the outstanding balance goes above this amount.\n  Order:\n    fields:\n      placedAt: { label: Placed on }\n\npages:\n  customers: { subtitle: Keep every relationship in view. }\n  orders: { subtitle: Every order and where it stands. }\n","smithable.ux.yml":"# How the app looks. Technology-neutral: presets and choices, never CSS.\nsmithableUx: 0.1\n\ntheme:\n  preset: corporate\n  density: compact          # an internal tool: more rows on screen\n\npages:\n  customers:\n    table:\n      columns: [name, email, segment, creditLimit]\n      below: { email: phone }   # the phone number under the email\n    form:\n      fieldOrder: [name, segment, email, phone]\n\ntones:\n  Order.status: { shipped: success, cancelled: danger }\n","smithable.yml":"smithable: 0.1\n\napp:\n  name: Acme CRM\n  description: Lightweight CRM for a small B2B sales team.\n  currency: EUR\n  timezone: Europe/Mariehamn\n\nmodels:\n  Customer:\n    description: A company we have a commercial relationship with.\n    fields:\n      name: string!\n      email: email unique\n      phone: phone\n      segment: smb | enterprise | government      # first value is the default\n      creditLimit:\n        type: money\n        min: 0\n        description: Maximum outstanding balance before new orders are held.\n      notes: text\n      accountManager: User\n      orders: Order[]                # every order that refers to this customer\n    ownedBy: accountManager          # the account manager owns the customer\n    access:                          # exceptions to \"shared\" (see smithable.auth.yml)\n      write: [sales]                 # any salesperson may edit any customer\n      delete: [admin]\n\n  Order:\n    fields:\n      number: string! unique\n      customer: Customer!\n      status: draft | placed | shipped | cancelled\n      total: money!\n      shippingMethod: standard | express\n      shippingCost:\n        type: money\n        formula: IF(AND(shippingMethod = \"standard\", total > 100), 0, IF(shippingMethod = \"express\", 15, 5))\n        description: Standard shipping is free above 100 EUR, otherwise 5 EUR. Express always costs 15 EUR.\n        examples:\n          - input: { total: 150, shippingMethod: standard }\n            expected: 0\n          - input: { total: 80, shippingMethod: standard }\n            expected: 5\n          - input: { total: 150, shippingMethod: express }\n            expected: 15\n      placedAt: datetime\n    access:\n      write: [sales]\n      delete: [admin]\n\nactions:\n  mergeCustomers:\n    custom: true\n    input: { keep: Customer!, duplicate: Customer! }\n    allow: [admin]\n    intent: Merge a duplicate customer record into the one we keep.\n    rules:\n      - All orders of the duplicate move to the kept customer.\n      - Empty fields on the kept customer are filled from the duplicate.\n      - The duplicate is deleted afterwards.\n\npages:\n  customers:\n    intent: Find a customer quickly and keep their details current.\n    crud: Customer\n    search: [name, email]\n    actions: [mergeCustomers]\n  orders:\n    crud: Order\n\nnavigation: [customers, orders]\n"},
  "invoicing": {"smithable.auth.yml":"# Who signs in, the roles and the default access. Technology-neutral.\nsmithableAuth: 0.1\n\nsignIn:\n  providers: [google]\n\ndefaultAccess: private             # each freelancer sees only their own data\n\nroles:\n  admin: { description: Invoicely staff. }\n  member: { description: A freelancer using Invoicely. }\n\nadmins: [owner@invoicely.example]\n\n# ⚠ PUBLIC: everything listed here is visible to anyone on the internet, without\n# signing in. Never add models that contain personal or business data.\npublic:\n  pages: [home]                    # the landing page\n","smithable.content.yml":"# What visitors read. Derived from names when not given here.\nsmithableContent: 0.1\n\npages:\n  home:\n    hero:\n      title: Get paid for your work, without the paperwork\n      subtitle: Invoicely keeps your clients, invoices and payments in one place, so you always know who owes you what.\n      button: Start invoicing\n    features:\n      title: Everything a freelancer needs\n      items:\n        - title: Invoices in a minute\n          text: Add the lines, and the total works itself out.\n        - title: See what is overdue\n          text: Every invoice shows whether it is a draft, sent, paid or overdue.\n        - title: Your clients in one place\n          text: Addresses and VAT numbers are there when you need them.\n    pricing:\n      title: Simple pricing\n      text: Example plans; the prices are illustrative.\n      items:\n        - name: Free\n          price: €0\n          period: per month\n          features: [Up to 5 clients, Unlimited invoices]\n          button: Start for free\n        - name: Pro\n          price: €9\n          period: per month\n          features: [Unlimited clients, Reminders for overdue invoices, Priority support]\n          button: Try Pro\n    faq:\n      title: Questions\n      items:\n        - question: Can I use my own invoice numbers?\n          answer: Yes. Numbers are yours to choose, like 2026-001.\n        - question: Who can see my invoices?\n          answer: Only you. Each freelancer sees their own clients and invoices.\n        - question: Can I change an invoice after sending it?\n          answer: A sent or paid invoice is not edited; you credit it instead.\n    callToAction:\n      title: Send your next invoice with Invoicely\n      button: Get started\n  overview:\n    subtitle: Who owes you what, at a glance.\n    outstanding: { label: Outstanding }\n    invoiced: { label: Invoiced by month }\n    latest: { label: Latest invoices }\n  invoices: { subtitle: Every invoice and where it stands. }\n  clients: { subtitle: The people and companies you work for. }\n  settings:\n    subtitle: Your business details, as your invoices show them.\n  welcome:\n    subtitle: A little setup now, and your invoices are ready to send.\n    business: { title: Your business }\n    payment:\n      title: Getting paid\n      text: Clients see these on every invoice.\n","smithable.ux.yml":"# How the app looks. Technology-neutral: presets and choices, never CSS.\nsmithableUx: 0.1\n\ntheme:\n  preset: modern\n\n# Status colours by meaning; values not listed are neutral.\ntones:\n  Invoice.status: { paid: success, overdue: warning }\n\npages:\n  invoices:\n    table:\n      columns: [number, client, status, issuedOn, total]\n","smithable.yml":"smithable: 0.1\n\napp:\n  name: Invoicely\n  description: Simple invoicing for freelancers. Each user manages their own clients and invoices.\n  currency: EUR\n\nmodels:\n  BusinessProfile:\n    description: The freelancer's own business details, printed on their invoices.\n    fields:\n      businessName: string!\n      vatNumber: string\n      iban: string\n      paymentTermDays: int! = 30\n      invoiceFooter: text\n\n  Client:\n    fields:\n      name: string!\n      email: email!\n      address: text\n      vatNumber: string\n      invoices: Invoice[]\n\n  Invoice:\n    fields:\n      number: string! unique\n      client: Client!\n      issuedOn: date! = TODAY()\n      dueOn:\n        type: date!\n        default: DATEADD(issuedOn, 30, \"day\")\n      status: draft | sent | paid | overdue\n      lines: InvoiceLine[]\n      total:\n        type: money\n        formula: SUM(lines.amount)\n    rules:\n      - Invoice numbers are sequential per user, like 2026-001, 2026-002.\n      - A sent or paid invoice can no longer be edited, only credited.\n\n  InvoiceLine:\n    fields:\n      invoice: Invoice!\n      description: string!\n      quantity: decimal! = 1\n      unitPrice: money!\n      amount:\n        type: money\n        formula: quantity * unitPrice\n        examples:\n          - input: { quantity: 3, unitPrice: 40 }\n            expected: 120\n          - input: { quantity: 0.5, unitPrice: 19.99 }\n            expected: 10\n\npages:\n  home:\n    route: /\n    landing:\n      hero: { button: overview }\n      features:\n      pricing:\n      faq:\n      callToAction: { button: overview }\n  overview:\n    dashboard:\n      outstanding: { sum: Invoice.total, where: { status: sent } }\n      overdue: { sum: Invoice.total, where: { status: overdue } }\n      paid: { sum: Invoice.total, where: { status: paid } }\n      invoiced: { sum: Invoice.total, by: issuedOn }\n      latest: { list: Invoice, limit: 5 }\n  invoices:\n    crud: Invoice\n  clients:\n    crud: Client\n  invoice-lines:\n    crud: InvoiceLine\n  settings:\n    settings: BusinessProfile\n  welcome:\n    onboarding:\n      model: BusinessProfile\n      steps:\n        business: [businessName, vatNumber]\n        payment: [iban, paymentTermDays]\n"},
};
